        /// <param name="filterHasNoSuggestionsInLang">Filter keys with no suggestions in lang</param>
        /// <param name="branch">Selects only keys from specified branch</param>
        /// <param name="filterDeletedByUserId">Filter trashed keys by who deleted them (user IDs)</param>
